138	             *(zb(k4,k1)*zab2(k1,k3,k4,k2)*za(k2,k5)
139	               -zb(k4,k2)*zab2(k2,k3,k4,k1)*za(k1,k5))
140	             *(za(k1,k3)*zb(k6,k2)/zab2(k1,k3,k4,k2)
141	               -za(k2,k3)*zb(k6,k1)/zab2(k2,k3,k4,k1));
142	
143	      Xpp(h3,h5) = app0 + mtsq*app2 + std::pow(mtsq, 2)*app4; // @coverage-probe
144	      // contribution to rational part (coefficient of mt^4)
145	      Xrat(2,2,h3,h5) = app4;
146	
147	      // Helicity 1^- 2^+
148	      amp2 = funcmp2(k1,k2,k3,k4,k5,k6) + funcmp2(k1,k2,k5,k6,k3,k4);
149	
150	      amp4 = two/(s(j1,j2)*s(k3,k4)*s(k5,k6)*std::pow(zab2(k2,k3,k4,k1), 2))
151	             *(za(k2,k5)*zb(k1,k4)*zab2(k1,k3,k4,k2)
152	               -za(k1,k5)*zb(k2,k4)*zab2(k2,k3,k4,k1))
153	             *(za(k2,k3)*zb(k1,k6)*zab2(k1,k3,k4,k2)
154	               -za(k1,k3)*zb(k2,k6)*zab2(k2,k3,k4,k1));
155	
156	      Xmp(h3,h5) = mtsq*amp2 + std::pow(mtsq, 2)*amp4;
157	      // contribution to rational part (coefficient of mt^4)
158	      Xrat(1,2,h3,h5) = amp4;
159	    }
160	  }
161	
162	  return;
163	}
